{
  "avaliacoes": [
    {
      "id": "E550117ce2043a3f9",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "O aumento de distância entre porto e unidades offshore tende a elevar o tempo médio de viagem das embarcações e a sobrecarregar a base de apoio, o que torna o planejamento logístico um elemento central da operação de suprimento.",
          "trechos": [
            "E550117ce2043a3f9:0:694"
          ],
          "condicoes": [
            "cenário de expansão do atendimento a novas unidades offshore",
            "operações de suprimento para exploração no pré-sal"
          ],
          "limites": [
            "o trecho trata de planejamento logístico em sentido amplo, não detalha critérios de aproximação, zonas de segurança ou posicionamento junto ao FPSO"
          ]
        },
        {
          "proposicao": "Na logística offshore, embarcações e aeronaves têm papéis distintos: embarcações são associadas ao transporte de cargas e aeronaves ao transporte de pessoas.",
          "trechos": [
            "E550117ce2043a3f9:694:1389"
          ],
          "condicoes": [
            "classificação funcional dos meios de transporte no contexto apresentado"
          ],
          "limites": [
            "não aborda exceções operacionais nem detalha interfaces entre ambos os modais"
          ]
        },
        {
          "proposicao": "Para PSV, o arranjo de carga no convés depende da área disponível, sem empilhamento e sem rotação das cargas, por razões de equilíbrio náutico; além disso, o atendimento considerado admite uma única embarcação por plataforma e menciona um tempo máximo de viagem de três dias sem retorno ao porto.",
          "trechos": [
            "E550117ce2043a3f9:1389:2081",
            "E550117ce2043a3f9:2081:2229"
          ],
          "condicoes": [
            "modelo operacional descrito para transporte de suprimentos por PSV",
            "cargas movimentadas por guindastes"
          ],
          "limites": [
            "o tempo máximo de três dias aparece como condição do sistema descrito, não como regra universal",
            "não há detalhamento de critérios de aproximação, posicionamento dinâmico ou interfaces com risers e ROV"
          ]
        }
      ]
    },
    {
      "id": "E1ea4142af6000f0a",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "O apoio logístico offshore concentra-se principalmente pelo mar para levar insumos às unidades de exploração e produção, enquanto helicópteros aparecem para pessoas ou pequenas cargas.",
          "trechos": [
            "E1ea4142af6000f0a:0:698"
          ],
          "condicoes": [
            "contexto de apoio offshore às unidades de exploração e produção"
          ],
          "limites": [
            "não detalha planejamento de interface marítima com FPSO nem critérios de prioridade logística"
          ]
        },
        {
          "proposicao": "Há especialização funcional entre tipos de embarcação de apoio: AHTS para suprimento, reboque e manejo de âncoras; PSV para transporte de cargas em convés, cabines e tanques; RSV para trabalhos submarinos com robô operado remotamente.",
          "trechos": [
            "E1ea4142af6000f0a:698:1397",
            "E1ea4142af6000f0a:1397:2094"
          ],
          "condicoes": [
            "tipologia de embarcações de apoio offshore apresentada pelo texto"
          ],
          "limites": [
            "a fonte descreve funções gerais e não especifica critérios de seleção entre embarcações para um FPSO concreto",
            "não informa controles operacionais de aproximação nem zonas de exclusão"
          ]
        },
        {
          "proposicao": "O deslocamento da produção para águas profundas e ultraprofundas é associado à necessidade de embarcações mais sofisticadas.",
          "trechos": [
            "E1ea4142af6000f0a:2094:2290"
          ],
          "condicoes": [
            "mudança do perfil da exploração offshore de águas rasas para profundas e ultraprofundas"
          ],
          "limites": [
            "não define quais sistemas ou capacidades adicionais são requeridos",
            "não trata explicitamente de posicionamento dinâmico, risers ou ROV na interface com FPSO"
          ]
        }
      ]
    },
    {
      "id": "E20dd09a8b7920038",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "AHTS é descrita como embarcação destinada a reboque, manuseio de âncoras e transporte de suprimentos, incluindo tubos, água doce, óleo, lama, salmoura, cimento e peças.",
          "trechos": [
            "E20dd09a8b7920038:0:699"
          ],
          "condicoes": [
            "descrição funcional geral de embarcação de apoio"
          ],
          "limites": [
            "os valores numéricos de porte e potência estão suprimidos",
            "não há explicação de interface específica com sistemas de ancoragem de FPSO"
          ]
        },
        {
          "proposicao": "RSV para operações de ROV é caracterizada como embarcação equipada com sistema de posicionamento dinâmico e outras instalações voltadas às operações com veículo de operação remota.",
          "trechos": [
            "E20dd09a8b7920038:699:1395"
          ],
          "condicoes": [
            "operações com ROV"
          ],
          "limites": [
            "a fonte não detalha lógica de controle do posicionamento, tolerâncias nem restrições em presença de risers e linhas submarinas"
          ]
        },
        {
          "proposicao": "A capacidade de combate a derramamento pode ser incorporada a um PSV ou AHTS, sugerindo compatibilidade funcional adicional além da função principal dessas embarcações.",
          "trechos": [
            "E20dd09a8b7920038:1395:2087",
            "E20dd09a8b7920038:2087:2252"
          ],
          "condicoes": [
            "contexto de resposta a derramamento de óleo"
          ],
          "limites": [
            "não esclarece requisitos de conversão, desempenho ou restrições operacionais dessa adaptação"
          ]
        }
      ]
    },
    {
      "id": "Ef68c1eead3f74c88",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "No arranjo contratual descrito, a Petrobras contrata serviços de apoio offshore por afretamento, e não como aquisição patrimonial das embarcações.",
          "trechos": [
            "Ef68c1eead3f74c88:699:1394"
          ],
          "condicoes": [
            "modelo contratual referido no texto",
            "contexto empresarial específico mencionado pela fonte"
          ],
          "limites": [
            "trata-se de descrição de arranjo contratual e contábil, não de regra geral para toda operação offshore"
          ]
        },
        {
          "proposicao": "Nos contratos de afretamento citados, além da embarcação, estão incluídos tripulação, víveres, tarifas portuárias e combustível.",
          "trechos": [
            "Ef68c1eead3f74c88:1394:2094"
          ],
          "condicoes": [
            "contratos de afretamento no modelo descrito"
          ],
          "limites": [
            "a fonte não discute variações contratuais possíveis nem critérios operacionais de desempenho"
          ]
        },
        {
          "proposicao": "AHTS é associada às operações de manuseio de âncoras, suprimento de plataformas e reboque, enquanto PSV é apresentada como embarcação projetada para grande capacidade de armazenagem para abastecer instalações offshore.",
          "trechos": [
            "Ef68c1eead3f74c88:1394:2094",
            "Ef68c1eead3f74c88:2094:2385"
          ],
          "condicoes": [
            "descrição das operações características dos tipos de embarcação"
          ],
          "limites": [
            "não especifica como essas capacidades se traduzem em critérios de seleção para cenários com risers, ROV ou zonas de segurança"
          ]
        }
      ]
    },
    {
      "id": "E9aaa4f3bcee0f45c",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A navegação de apoio offshore é apresentada como principal meio de apoio logístico às unidades de exploração e produção, em contraste com o uso aéreo para pessoas ou pequenas cargas.",
          "trechos": [
            "E9aaa4f3bcee0f45c:0:695"
          ],
          "condicoes": [
            "contexto de apoio logístico offshore"
          ],
          "limites": [
            "não aprofunda integração com operações de helicópteros ou SIMOPS"
          ]
        },
        {
          "proposicao": "AHTS e PSV aparecem como os tipos mais numerosos, com AHTS voltado a suprimento, reboque e manejo de âncoras e PSV ao transporte de cargas em convés, cabines e tanques.",
          "trechos": [
            "E9aaa4f3bcee0f45c:695:1395"
          ],
          "condicoes": [
            "classificação de tipos de embarcação de apoio"
          ],
          "limites": [
            "não detalha critérios de escolha entre classes nem limitações de aproximação"
          ]
        },
        {
          "proposicao": "RSV realiza manutenção submarina e mapeamento do leito oceânico por meio de robô controlado remotamente, enquanto OSCV realiza construção submarina, como lançamento de dutos; MPSV combina capacidades de diferentes embarcações de apoio.",
          "trechos": [
            "E9aaa4f3bcee0f45c:1395:2087",
            "E9aaa4f3bcee0f45c:2087:2265"
          ],
          "condicoes": [
            "operações de natureza submarina e construção subsea"
          ],
          "limites": [
            "a fonte não trata da interface operacional dessas atividades com FPSO, risers instalados ou zonas de exclusão"
          ]
        }
      ]
    },
    {
      "id": "E34f5f72bf8b2c3b3",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Unidades marítimas precisam de atendimento regular porque, por restrições de espaço e estabilidade, não conseguem armazenar todos os suprimentos requeridos, tornando necessário o transporte periódico a partir de base continental.",
          "trechos": [
            "E34f5f72bf8b2c3b3:691:1387"
          ],
          "condicoes": [
            "operações regulares de suprimento às unidades marítimas"
          ],
          "limites": [
            "não define frequência ótima nem critérios quantitativos de estoque"
          ]
        },
        {
          "proposicao": "A falta de atendimento de uma demanda de unidade marítima pode interromper o trabalho a bordo e gerar perda econômica relevante.",
          "trechos": [
            "E34f5f72bf8b2c3b3:691:1387"
          ],
          "condicoes": [
            "existência de demanda não atendida de insumos ou materiais necessários"
          ],
          "limites": [
            "o trecho aponta consequência operacional geral, sem quantificação e sem distinguir criticidades por tipo de carga"
          ]
        },
        {
          "proposicao": "PSV é descrito como o tipo mais utilizado para transporte marítimo até plataformas, especializado no apoio a plataformas de perfuração ou produção, navios-sonda e embarcações maiores, transportando combustíveis, água, produtos químicos, tubulações, ferramentas, granéis, rancho e cimento; o porte do navio é relacionado à capacidade de armazenagem, área de convés e quantidade de tanques.",
          "trechos": [
            "E34f5f72bf8b2c3b3:691:1387",
            "E34f5f72bf8b2c3b3:1387:2085",
            "E34f5f72bf8b2c3b3:2085:2220"
          ],
          "condicoes": [
            "descrição geral do emprego de PSV em apoio marítimo"
          ],
          "limites": [
            "as faixas numéricas de TPB estão apagadas",
            "não há detalhamento sobre posicionamento, aproximação segura ou compatibilidade com risers e ROV"
          ]
        }
      ]
    }
  ],
